package com.jmadsen.dashhop;
import java.util.*;import java.io.*;import java.nio.file.*;import org.json.*;import android.content.*;import android.content.res.Resources;import android.util.DisplayMetrics;
public class Increment03Test {
 static int checks;static void check(boolean value,String reason){checks++;if(!value)throw new AssertionError(reason);}
 static class Device extends Context {Map<String,RepositoryPolicyTest.Memory> spaces=new HashMap<>();File folder;Device()throws Exception{folder=Files.createTempDirectory("dashhop-diag-test").toFile();}public SharedPreferences getSharedPreferences(String name,int mode){return spaces.computeIfAbsent(name,x->new RepositoryPolicyTest.Memory());}public Resources getResources(){return new Resources(new DisplayMetrics());}public File getFilesDir(){return folder;}}
 public static void main(String[] args)throws Exception{
 AutoCollapsePolicy a=new AutoCollapsePolicy();a.configure(true,3,0);a.visible(true,true,0);check(!a.due(2999)&&a.due(3000),"Default three-second idle boundary");a.touch(true,2800);check(a.waitMillis(9000)==-1&&!a.due(9000),"Finger down cancels collapse");a.touch(false,10000);check(!a.due(12999)&&a.due(13000),"Finger lift restarts full delay");a.scroll(12000);check(!a.due(14999)&&a.due(15000),"Fling scroll movement restarts idle deadline");a.menu(true,14000);check(!a.due(50000),"Open menu blocks collapse");a.menu(false,20000);check(a.due(23000),"Menu dismissal starts fresh idle period");a.visible(false,true,21000);check(!a.due(50000)&&a.waitMillis(50000)==-1,"Settings visibility pauses collapse");a.visible(true,true,60000);check(!a.due(62000)&&a.due(63000),"Leaving Settings arms once");a.sleep();check(a.waitMillis(90000)==-1,"Sleep cancels old deadline");a.visible(true,true,100000);check(!a.due(100001)&&a.due(103000),"Wake starts a fresh delay");a.configure(true,0,200000);check(!a.due(200001)&&!a.due(200250)&&a.waitMillis(999999)==-1,"Zero disables timed collapse");a.touch(true,200200);check(!a.due(999999),"Zero never interrupts held touch");a.touch(false,201010);check(!a.due(201250),"Zero remains disabled after lift");a.configure(false,3,202000);a.scroll(203000);check(!a.due(999999)&&a.waitMillis(999999)==-1,"Disabled remains manual");a.configure(true,99,300000);check(!a.due(314999)&&a.due(315000),"Delay clamps to 15 seconds");a.visible(true,false,300000);check(a.waitMillis(999999)==-1,"Collapsed handle has no countdown");a.visible(true,true,400000);check(a.waitMillis(400000)==15000,"Re-expansion restarts current preference");
 for(DrivingStateProvider.State s:DrivingStateProvider.State.values()){check(LaunchSafety.allowed(false,s),"Ordinary app stays available");check(LaunchSafety.allowed(true,s)==(s==DrivingStateProvider.State.PARKED_VERIFIED),"Explicit parked-only fail closed");}
 RepositoryPolicyTest.Memory memory=new RepositoryPolicyTest.Memory();String first=DiagnosticIdentity.get(memory);check(DiagnosticIdentity.get(memory).equals(first),"ID stable on repeated lookup");check(!DiagnosticIdentity.get(new RepositoryPolicyTest.Memory()).equals(first),"Different install gets different ID");memory.putString("device_id","invalid").apply();check(!DiagnosticIdentity.get(memory).equals("invalid"),"Malformed ID repaired");
 Device unit=new Device();Thread.UncaughtExceptionHandler prior=Thread.getDefaultUncaughtExceptionHandler();Diagnostics.init(unit);Thread.setDefaultUncaughtExceptionHandler(prior);String id=Diagnostics.id;new ShortcutRepository(unit).reset();check(DiagnosticIdentity.get(unit.getSharedPreferences("diagnostic_identity",0)).equals(id),"Dock reset keeps separate diagnostic identity");String detail=new String(new char[900]).replace('\0','x');for(int i=0;i<1150;i++)Diagnostics.write("rotation_test",detail);File[] files=Diagnostics.dir.listFiles();check(files.length<=5&&files.length>=2,"Bounded log rotation exercised");ByteArrayOutputStream out=new ByteArrayOutputStream();Diagnostics.export(out);String exported=out.toString("UTF-8");int headers=0,events=0;for(String line:exported.split("\n")){JSONObject o=new JSONObject(line);check(o.getString("device_id").equals(id),"Every header/event carries same device ID");check(o.has("session_id"),"Every line has capture-session identity");if(o.optString("type").equals("dashhop_log_header")){headers++;check(o.getJSONObject("head_unit").getString("model").equals("Host-test model"),"Header contains profile");check(o.getInt("version_code")==20102,"Header contains app version");}else events++;}check(headers>=3&&events>0,"Export header plus rotated-file headers retained");check(!exported.contains("weatherLat")&&!exported.contains("latitude")&&!exported.contains("serial_number")&&!exported.contains("imei"),"No coordinates or hardware serial in default logs");
 String raw=new String(Files.readAllBytes(Paths.get(args[0])),java.nio.charset.StandardCharsets.UTF_8);WeatherData w=new WeatherData(new JSONObject(raw),"API test fixture",1000);check(Double.isFinite(w.temperature),"Live API fixture parsed by production model");check(!w.stale(1001)&&w.stale(1801000)&&w.stale(999),"Weather stale / clock rollback detection");check(WeatherData.degrees(0,true).equals("32°F")&&WeatherData.degrees(100,false).equals("100°C"),"Unit conversion");check(WeatherData.time(1700000000L,"UTC")==1700000000000L,"Epoch API timestamps");check(WeatherData.time("2026-10-16T10:00","UTC")==java.time.Instant.parse("2026-10-16T10:00:00Z").toEpochMilli(),"ISO current/hourly fixture timestamps");check(WeatherData.time("2026-10-16","UTC")==java.time.Instant.parse("2026-10-16T00:00:00Z").toEpochMilli(),"ISO daily timestamps");boolean rejected=false;try{new WeatherData(new JSONObject("{\"error\":true}"),"x",0);}catch(Exception e){rejected=true;}check(rejected,"Provider error rejected");rejected=false;try{DirectOpenMeteoProvider.coordinates(Double.NaN,0);}catch(Exception e){rejected=true;}check(rejected,"Invalid location rejected");check(!new PhoneWeatherProvider().available(),"Phone source honestly unavailable");
 System.out.println("PASS: "+checks+" timer, launch-safety, identity/log rotation/export and weather assertions. Host adapters only; no Android UI/device tests.");
 }
}